import { Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {Array<number>} position
 * @property {Array<number>} rotation
 * @property {Array<number>} scale
 * @property {Array<Object>} cinematicPrimitives
 *
 * @typedef {Object} NodeContext
 * @property {(url:string)=>import('three').Texture} textureLoader
 * @property {Record<string,Function>} primitives
 * @property {(event:string)=>void} emit
 */

/**
 * Create a textured quote‑panel node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { assets, position, rotation, scale, cinematicPrimitives = [] } = config;

  // ---- texture --------------------------------------------------------------
  const texture = ctx.textureLoader(assets.imageUrl);

  // ---- geometry -------------------------------------------------------------
  // Preserve image aspect (default fallback 1).
  const imgWidth = texture?.image?.width || 512;
  const imgHeight = texture?.image?.height || 320;
  const aspect = imgWidth / imgHeight;
  const geometry = new PlaneGeometry(aspect, 1);

  // ---- material --------------------------------------------------------------
  const material = new MeshBasicNodeMaterial({ map: texture, toneMapped: false });

  // ---- mesh -----------------------------------------------------------------
  const mesh = new Mesh(geometry, material);
  mesh.position.set(position[0], position[1], position[2]);
  mesh.rotation.set(rotation[0], rotation[1], rotation[2]);
  mesh.scale.set(scale[0], scale[1], scale[2]);

  // ---- cinematic primitives --------------------------------------------------
  cinematicPrimitives.forEach((prim) => {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      fn(mesh, prim.params);
    }
  });

  // ---- interaction timelines -------------------------------------------------
  const originalY = mesh.position.y;
  const hoverTL = gsap.timeline({ paused: true });
  hoverTL.to(
    mesh.position,
    {
      y: originalY + 0.15,
      duration: 0.15,
      ease: 'power3.out',
    },
    0,
  );

  const pressTL = gsap.timeline({ paused: true });
  pressTL.to(
    mesh.scale,
    {
      x: mesh.scale.x * 0.97,
      y: mesh.scale.y * 0.97,
      z: mesh.scale.z * 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    },
    0,
  );

  // ---- userData handlers -----------------------------------------------------
  mesh.userData.handlers = {};

  mesh.userData.handlers.hover = (enter) => {
    if (enter) {
      hoverTL.play();
    } else {
      hoverTL.reverse();
    }
  };

  mesh.userData.handlers.click = () => {
    pressTL.restart();
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-pricing.select');
    }
  };

  // ---- cleanup ---------------------------------------------------------------
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture?.dispose) texture.dispose();
    hoverTL.kill();
    pressTL.kill();
  };

  return mesh;
}
